import{_ as s,o as a,c as r,a2 as e,j as d,a as n,t as l}from"./chunks/framework.C4u7U0Dw.js";const k=JSON.parse('{"title":"第 27 章 团队模板与工作流编排","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第五篇 平台能力全景/第 27 章 团队模板与工作流编排.md","filePath":"bluebook/第五篇 平台能力全景/第 27 章 团队模板与工作流编排.md"}'),p={name:"bluebook/第五篇 平台能力全景/第 27 章 团队模板与工作流编排.md"},i={tabindex:"0"},u={tabindex:"0"};function h(o,t,g,c,q,b){return a(),r("div",null,[t[22]||(t[22]=e(`<h1 id="第-27-章-团队模板与工作流编排" tabindex="-1">第 27 章 团队模板与工作流编排 <a class="header-anchor" href="#第-27-章-团队模板与工作流编排" aria-label="Permalink to &quot;第 27 章 团队模板与工作流编排&quot;">​</a></h1><blockquote><p>本章目标：把&quot;每次临时拉一队人&quot;升级成&quot;<strong>一句话启动一支现成的队</strong>&quot;。你会看到 3 套内置模板的完整拆解，以及模板背后的编排机制——<strong>它为什么能自动把上一步的产出喂给下一步</strong>。</p></blockquote><h2 id="_27-1-从-召唤队友-到-固化队形" tabindex="-1">27.1 从&quot;召唤队友&quot;到&quot;固化队形&quot; <a class="header-anchor" href="#_27-1-从-召唤队友-到-固化队形" aria-label="Permalink to &quot;27.1 从&quot;召唤队友&quot;到&quot;固化队形&quot;&quot;">​</a></h2><p>第 8 章讲过怎么临时召唤一支 AI 团队。但如果你每周都要做同一类事，每次都要：</p><ol><li>想清楚要几个角色；</li><li>一个个分配任务；</li><li>手动把上一步的产出复制给下一步……</li></ol><p><strong>这套动作重复三遍以上，就该固化了。</strong></p><p>团队模板要解决的就是这个：<strong>把&quot;角色组合 + 分工顺序 + 交付物传递&quot;打包成一个可复用的模板。</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>临时组队</th><th>团队模板</th></tr></thead><tbody><tr><td>启动方式</td><td>每次口头描述</td><td>一句话 / 一个按钮</td></tr><tr><td>角色配置</td><td>现场想</td><td>预置好</td></tr><tr><td>步骤顺序</td><td>你来盯</td><td>模板写死</td></tr><tr><td>产出传递</td><td>手动转述</td><td><strong>自动注入</strong></td></tr><tr><td>可复用性</td><td>低</td><td>高</td></tr><tr><td>适合</td><td>一次性复杂任务</td><td>周期性、有固定套路的工作</td></tr></tbody></table><h2 id="_27-2-一个团队模板由什么组成" tabindex="-1">27.2 一个团队模板由什么组成 <a class="header-anchor" href="#_27-2-一个团队模板由什么组成" aria-label="Permalink to &quot;27.2 一个团队模板由什么组成&quot;">​</a></h2><p>一套模板 = <strong>角色表（roles）</strong> + <strong>工作流（workflows）</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模板</span></span>
<span class="line"><span>├── 角色表 roles[]</span></span>
<span class="line"><span>│   ├── 后端架构师  ⚙️   (slotIndex 0)</span></span>
<span class="line"><span>│   ├── 快速原型师  ⚡   (slotIndex 1)</span></span>
<span class="line"><span>│   └── 现实检验者  🎯   (slotIndex 2)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── 工作流 workflows[]</span></span>
<span class="line"><span>    └── 步骤 steps[]</span></span>
<span class="line"><span>        ├── ① plan      由角色 0 执行 → 产出 plan_doc</span></span>
<span class="line"><span>        ├── ② implement 由角色 1 执行 → 依赖 plan，产出 code</span></span>
<span class="line"><span>        └── ③ review    由角色 2 执行 → 依赖 implement，产出 review_result</span></span></code></pre></div><p>两个细节值得注意：</p><ul><li>角色有<strong>槽位（slotIndex）</strong>，步骤通过 <code>roleIndex</code> 指向角色——<strong>所以&quot;谁做哪一步&quot;是设计好的，不是随机分配</strong>；</li><li>每个步骤有<strong>输出键（outputKey）</strong>，后面的步骤可以直接引用。</li></ul><h2 id="_27-3-三套内置模板" tabindex="-1">27.3 三套内置模板 <a class="header-anchor" href="#_27-3-三套内置模板" aria-label="Permalink to &quot;27.3 三套内置模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模板</th><th>分类</th><th>难度</th><th>角色数</th><th>步骤数</th><th>适合谁</th></tr></thead><tbody><tr><td>软件开发标准流程</td><td>通用</td><td>进阶</td><td>5</td><td>5</td><td>要正经交付一个软件/系统功能</td></tr><tr><td>一人公司·做内容</td><td>通用</td><td>进阶</td><td>5</td><td>5</td><td>个人或小团队做内容运营</td></tr><tr><td>Codex + Claude Code 协作编程（极简版）</td><td>开发</td><td>中级</td><td>3</td><td>3</td><td>要快速验证一个技术想法</td></tr></tbody></table><h3 id="_27-3-1-软件开发标准流程-5-角色-·-5-步" tabindex="-1">27.3.1 软件开发标准流程（5 角色 · 5 步） <a class="header-anchor" href="#_27-3-1-软件开发标准流程-5-角色-·-5-步" aria-label="Permalink to &quot;27.3.1 软件开发标准流程（5 角色 · 5 步）&quot;">​</a></h3><p>这是最值得学的一套，因为它<strong>模拟的就是真实软件团队的交付链路</strong>：</p><table tabindex="0"><thead><tr><th>步</th><th>步骤码</th><th>谁来做</th><th>产出</th><th>依赖</th></tr></thead><tbody><tr><td>1</td><td><code>clarify</code></td><td>📦 产品经理</td><td>需求规格 <code>spec</code></td><td>—</td></tr><tr><td>2</td><td><code>design</code></td><td>🏛️ 软件架构师</td><td>技术方案 <code>plan</code></td><td>clarify</td></tr><tr><td>3</td><td><code>implement</code></td><td>👨💻 高级开发者</td><td>代码 <code>code</code></td><td>design</td></tr><tr><td>4</td><td><code>review</code></td><td>👀 代码审查员</td><td>审查意见 <code>review</code></td><td>implement</td></tr><tr><td>5</td><td><code>verify</code></td><td>🎯 现实检验者</td><td>验收结论 <code>acceptance</code></td><td>review</td></tr></tbody></table><p><strong>它的流程逻辑是</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>产品经理把需求问清楚（clarify）</span></span>
<span class="line"><span>   ↓ 需求规格自动传给架构师</span></span>
<span class="line"><span>架构师出技术方案（design）</span></span>
<span class="line"><span>   ↓ 方案自动传给开发者</span></span>
<span class="line"><span>开发者写代码（implement）</span></span>
<span class="line"><span>   ↓ 代码自动传给审查员</span></span>
<span class="line"><span>审查员挑问题（review）</span></span>
<span class="line"><span>   ↓ 审查意见自动传给检验者</span></span>
<span class="line"><span>检验者做最终验收（verify）</span></span></code></pre></div><p><strong>为什么这个顺序是&quot;对的&quot;？</strong></p><p>因为它杜绝了两种最常见的返工：</p><ul><li>❌ 需求没澄清就写代码 → 做得越快，废得越彻底</li><li>❌ 代码没审查就上线 → 出问题才发现没人复核</li></ul><blockquote><p>这套模板最大的价值不是&quot;AI 帮你写代码&quot;，而是<strong>它强迫你走完一个专业流程</strong>。哪怕你自己是资深工程师，借它跑一遍也能发现漏掉的环节。</p></blockquote><p><strong>补充</strong>：这套模板支持把产出<strong>真正落地成文件</strong>（materialize 模式）——最后的代码不是&quot;聊天里的代码块&quot;，而是写到工作区里的真实文件。</p><h3 id="_27-3-2-一人公司·做内容-5-角色-·-5-步" tabindex="-1">27.3.2 一人公司·做内容（5 角色 · 5 步） <a class="header-anchor" href="#_27-3-2-一人公司·做内容-5-角色-·-5-步" aria-label="Permalink to &quot;27.3.2 一人公司·做内容（5 角色 · 5 步）&quot;">​</a></h3><p>这套非常适合个人创作者和小团队，它模拟的是<strong>一个内容公司的完整班底</strong>：</p><table tabindex="0"><thead><tr><th>步</th><th>步骤码</th><th>谁来做</th><th>干什么</th><th>产出</th></tr></thead><tbody><tr><td>1</td><td><code>ceo_position</code></td><td>🧭 老板/CEO</td><td>定内容方向与商业定位</td><td>定位 <code>position</code></td></tr><tr><td>2</td><td><code>audience</code></td><td>🔍 用户研究员</td><td>分析目标读者在想什么</td><td>受众洞察</td></tr><tr><td>3</td><td><code>topics</code></td><td>✍️ 内容策划</td><td>出选题与内容框架</td><td>选题清单</td></tr><tr><td>4</td><td><code>script</code></td><td>🎵 编导</td><td>写脚本/文案</td><td>脚本</td></tr><tr><td>5</td><td><code>calendar</code></td><td>📱 运营</td><td>排发布节奏与分发</td><td>发布日历</td></tr></tbody></table><p><strong>它的精妙之处在于顺序</strong>：</p><p>先定<strong>方向</strong>（CEO 视角），再研究<strong>人</strong>（研究员视角），然后才是<strong>内容和排期</strong>。</p><p>对比一下大多数人的做法——一上来就想&quot;这周发什么&quot;，结果发了一堆没人看的东西。<strong>这套模板解决的不是&quot;写不出来&quot;，而是&quot;写错了方向&quot;。</strong></p><p><strong>它还支持变量注入</strong>：启动时你只填一句&quot;我要做什么方向的内容&quot;，这个变量会贯穿后面所有步骤。</p><h3 id="_27-3-3-codex-claude-code-协作编程-极简版-3-角色-·-3-步" tabindex="-1">27.3.3 Codex + Claude Code 协作编程（极简版）（3 角色 · 3 步） <a class="header-anchor" href="#_27-3-3-codex-claude-code-协作编程-极简版-3-角色-·-3-步" aria-label="Permalink to &quot;27.3.3 Codex + Claude Code 协作编程（极简版）（3 角色 · 3 步）&quot;">​</a></h3><p>最小可用的技术验证队：</p>`,34)),d("table",i,[t[16]||(t[16]=d("thead",null,[d("tr",null,[d("th",null,"步"),d("th",null,"步骤码"),d("th",null,"谁来做"),d("th",null,"任务模板")])],-1)),d("tbody",null,[d("tr",null,[t[2]||(t[2]=d("td",null,"1",-1)),t[3]||(t[3]=d("td",null,[d("code",null,"plan")],-1)),t[4]||(t[4]=d("td",null,"⚙️ 后端架构师",-1)),d("td",null,[t[0]||(t[0]=n("做技术规划：实现思路、模块拆分、验收标准（输入：",-1)),d("code",null,l(o.requirement),1),t[1]||(t[1]=n("）",-1))])]),d("tr",null,[t[7]||(t[7]=d("td",null,"2",-1)),t[8]||(t[8]=d("td",null,[d("code",null,"implement")],-1)),t[9]||(t[9]=d("td",null,"⚡ 快速原型师",-1)),d("td",null,[t[5]||(t[5]=n("严格按规划与验收标准实现代码（输入：",-1)),d("code",null,l(o.plan_doc),1),t[6]||(t[6]=n("）",-1))])]),d("tr",null,[t[13]||(t[13]=d("td",null,"3",-1)),t[14]||(t[14]=d("td",null,[d("code",null,"review")],-1)),t[15]||(t[15]=d("td",null,"🎯 现实检验者",-1)),d("td",null,[t[10]||(t[10]=n("对照验收标准复核代码（输入：",-1)),d("code",null,l(o.plan_doc),1),t[11]||(t[11]=n(" + ",-1)),d("code",null,l(o.code),1),t[12]||(t[12]=n("）",-1))])])])]),t[23]||(t[23]=e(`<p><strong>注意第 3 步的任务描述</strong>：它同时引用了第 1 步的验收标准<strong>和</strong>第 2 步的代码。</p><blockquote><p>这就是模板的威力：<strong>审查者手里同时拿着&quot;承诺&quot;和&quot;交付&quot;，对照着看。</strong> 这在人工协作里往往做不到——因为没人记得把原始标准翻出来。</p></blockquote><h2 id="_27-4-编排机制-模板为什么能自动接力" tabindex="-1">27.4 编排机制：模板为什么能自动接力 <a class="header-anchor" href="#_27-4-编排机制-模板为什么能自动接力" aria-label="Permalink to &quot;27.4 编排机制：模板为什么能自动接力&quot;">​</a></h2><p>这一节稍微技术一点，但理解了它你就能改模板。</p><h3 id="_27-4-1-四个关键字段" tabindex="-1">27.4.1 四个关键字段 <a class="header-anchor" href="#_27-4-1-四个关键字段" aria-label="Permalink to &quot;27.4.1 四个关键字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>作用</th><th>例子</th></tr></thead><tbody><tr><td><code>outputKey</code></td><td>这一步的产出叫什么名字</td><td><code>plan_doc</code>、<code>code</code>、<code>review_result</code></td></tr><tr><td><code>dependsOn</code></td><td>这一步要等谁完成</td><td><code>[&quot;plan&quot;]</code></td></tr><tr><td><code>dependsMode</code></td><td>依赖怎么算满足</td><td><code>all</code>（全部完成）</td></tr><tr><td><code>maxIterations</code></td><td>这一步最多重试几次</td><td><code>1</code></td></tr></tbody></table><p><strong>它们合起来实现了&quot;接力&quot;</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① plan 产出 plan_doc</span></span>
<span class="line"><span>② implement 的 dependsOn=[&quot;plan&quot;] 满足 → 启动</span></span>
<span class="line"><span>   任务里写 {{plan_doc}} → 自动替换为第①步的实际产出</span></span>
<span class="line"><span>③ review 的 dependsOn=[&quot;implement&quot;] 满足 → 启动</span></span>
<span class="line"><span>   任务里写 {{plan_doc}} 和 {{code}} → 两个产出都注入</span></span></code></pre></div><h3 id="_27-4-2-变量注入-模板可复用的关键" tabindex="-1">27.4.2 变量注入：模板可复用的关键 <a class="header-anchor" href="#_27-4-2-变量注入-模板可复用的关键" aria-label="Permalink to &quot;27.4.2 变量注入：模板可复用的关键&quot;">​</a></h3><p>任务文本里可以写占位符：</p>`,10)),d("table",u,[t[21]||(t[21]=d("thead",null,[d("tr",null,[d("th",null,"占位符"),d("th",null,"来源")])],-1)),d("tbody",null,[d("tr",null,[d("td",null,[d("code",null,l(o.requirement),1),t[17]||(t[17]=n("、",-1)),d("code",null,l(o.direction),1)]),t[18]||(t[18]=d("td",null,[d("strong",null,"你启动模板时填的")],-1))]),d("tr",null,[d("td",null,[d("code",null,l(o.plan_doc),1),t[19]||(t[19]=n("、",-1)),d("code",null,l(o.code),1)]),t[20]||(t[20]=d("td",null,[d("strong",null,"前面步骤的产出")],-1))])])]),t[24]||(t[24]=e('<p><strong>这两种变量的区别非常重要</strong>：</p><ul><li>前者让模板<strong>通用</strong>（同一个模板能做不同的内容）；</li><li>后者让步骤<strong>接力</strong>（不用你手动搬运）。</li></ul><h3 id="_27-4-3-并发控制" tabindex="-1">27.4.3 并发控制 <a class="header-anchor" href="#_27-4-3-并发控制" aria-label="Permalink to &quot;27.4.3 并发控制&quot;">​</a></h3><p>工作流有一个 <code>concurrency</code> 字段，模板整体也有 <code>maxConcurrent</code>。</p><p>意思很简单：<strong>同时最多几个队友在干活</strong>。</p><ul><li>设成 1 → 严格串行，一步接一步（结果最可控）</li><li>调高 → 允许并行的步骤同时跑（速度快，但要小心依赖关系）</li></ul><blockquote><p>实践建议：<strong>先用默认值，确认流程跑得顺了再调并发。</strong> 并行不是越快越好，顺序敏感的步骤并行反而会乱。</p></blockquote><h2 id="_27-5-什么时候该做自己的模板" tabindex="-1">27.5 什么时候该做自己的模板 <a class="header-anchor" href="#_27-5-什么时候该做自己的模板" aria-label="Permalink to &quot;27.5 什么时候该做自己的模板&quot;">​</a></h2><p>判断标准很简单——<strong>同一套&quot;多人配合流程&quot;你走了三次以上</strong>，就该固化。</p><table tabindex="0"><thead><tr><th>你的情况</th><th>建议</th></tr></thead><tbody><tr><td>一次性复杂任务</td><td>临时组队（第 8 章）</td></tr><tr><td>偶尔做、但流程固定</td><td>让队友记住分工即可</td></tr><tr><td><strong>周期性 + 多角色 + 有固定交付物</strong></td><td>✅ 做成模板</td></tr><tr><td>只是重复同一个单人动作</td><td>别做模板，做成 Skill（第 17 章）</td></tr></tbody></table><p><strong>常见的自建模板场景</strong>：</p><ul><li>每周的行业情报汇总（研究员 → 分析师 → 编辑）</li><li>每月的经营分析（数据整理 → 财务模型 → 汇报 PPT）</li><li>客户提案（需求澄清 → 方案 → 报价 → 复核）</li><li>内容日历（选题 → 脚本 → 视觉 → 排期）</li></ul><blockquote><p>区分口诀：<strong>一个人反复做 → Skill；一队人按顺序做 → 团队模板。</strong></p></blockquote><h2 id="_27-6-本章练习" tabindex="-1">27.6 本章练习 <a class="header-anchor" href="#_27-6-本章练习" aria-label="Permalink to &quot;27.6 本章练习&quot;">​</a></h2><ol><li><strong>跑一遍内置模板</strong>：挑&quot;软件开发标准流程&quot;或&quot;一人公司·做内容&quot;，用一个真实需求走完全程，留意每一步的产出是怎么传到下一步的。</li><li><strong>找你的固定套路</strong>：写出你工作里&quot;至少三个人、按固定顺序、周期性地&quot;要走的流程。</li><li><strong>设计你的第一套模板</strong>：只需写出三样——角色有谁、步骤有哪些、每步产出叫什么名字。剩下的可以交给我。</li></ol><hr><blockquote><p>小结：团队模板把&quot;人 × 顺序 × 产出&quot;固化下来，让专业流程变成<strong>一键可复用</strong>的资产。<strong>你重复三次的协作方式，就值得变成一套模板</strong>——这是从&quot;用 AI 干活&quot;到&quot;用 AI 组队&quot;的分界线。</p></blockquote>',17))])}const _=s(p,[["render",h]]);export{k as __pageData,_ as default};
